import { describe, expect, test } from 'bun:test'
import { SUITS, type Card } from '../../src/games/cards/model'
import { at, asksColumn, autoHome, cascadeGap, cardsLeft, deal, emptyStats, hasLegalMove, homeIndex, homeSequence, legal, move, moveSource, needsResign, parseNumber, peekSource, pointerSource, record, safeHome, selectSource, snapshot, supermoveLimit, undo, validNumber, won,
  type Board, type Game } from '../../src/games/freecell/engine'
import { S } from '../../src/games/freecell/strings'

// External fixtures, not generated by the implementation under test:
// https://rosettacode.org/wiki/Deal_cards_for_FreeCell (task table and Ada output).
const fixtures: Record<number, string> = {
  1: `JD 2D 9H JC 5D 7H 7C 5H KD KC 9S 5S AD QC KH 3H 2S KS 9D QD JS AS AH 3C 4C 5C TS QH 4H AC 4D 7S
    3S TD 4S TH 8H 2C JH 7D 6D 8S 8D QS 6C 3D 8C TC 6S 9C 2H 6H`,
  617: `7D AD 5C 3S 5S 8C 2D AH TD 7S QD AC 6D 8H AS KH TH QC 3H 9D 6S 8D 3D TC KD 5H 9S 3C 8S 7H 4D JS
    4C QS 9C 9H 7C 6H 2C 2S 4S TS 2H 5D JC 6C JH QH JD KS KC 4H`,
  11982: `AH AS 4H AC 2D 6S TS JS 3D 3H QS QC 8S 7H AD KS KD 6H 5S 4D 9H JH 9S 3C JC 5D 5C 8C 9D TD KH 7C
    6C 2C TH QH 6D TC 4S 7S JD 7D 8H 9C 2H QD 4C 5H KC 8D 2S 3S`
}
const c = (rank: number, suit = 0): Card => ({ id: (rank - 1) * 4 + suit, rank, suit: SUITS[suit], faceUp: true })
const home = (rank: number, suit: number) => Array.from({ length: rank }, (_, i) => c(i + 1, suit))
function board(): Board { return { cascades: Array.from({ length: 8 }, () => []), free: [null, null, null, null], home: [[], [], [], []] } }
function game(b: Board): Game { return { ...b, number: 1, history: [], cheat: false, moves: 0 } }

describe('Microsoft FreeCell', () => {
  for (const number of [1, 617, 11982]) test(`all 52 externally sourced cards for #${number}`, () => {
    const g = deal(number)
    fixtures[number].trim().split(/\s+/).forEach((token, i) => {
      const card = g.cascades[i % 8][Math.floor(i / 8)]
      expect('A23456789TJQK'[card.rank - 1] + 'CDHS'[SUITS.indexOf(card.suit)]).toBe(token)
    })
    expect(g.cascades.map(p => p.length)).toEqual([7, 7, 7, 7, 6, 6, 6, 6])
    expect(new Set(g.cascades.flat().map(c => c.id)).size).toBe(52)
    expect(deal(number)).toEqual(g)
  })
  test('hidden games fixed and distinct with every ace buried', () => {
    for (const number of [-1, -2]) {
      const g = deal(number)
      expect(deal(number)).toEqual(g)
      expect(g.cascades.slice(0, 4).map(p => p[0].rank)).toEqual([1, 1, 1, 1])
      expect(new Set(g.cascades.flat().map(c => c.id)).size).toBe(52)
    }
    expect(deal(-1).cascades).not.toEqual(deal(-2).cascades)
    expect(deal(-2).cascades[0].map(c => c.rank)).toEqual([1, 13, 12, 11, 10, 9, 8])
  })
  test('supermove excludes empty destination, counts occupied destination normally', () => {
    const b = board()
    b.cascades.forEach((p, i) => { if (i < 6) p.push(c(13, i % 4)) })
    expect(supermoveLimit(b, 0)).toBe(20)
    expect(supermoveLimit(b, 7)).toBe(10)
    b.free[0] = c(8)
    expect(supermoveLimit(b, 7)).toBe(8)
    b.free.fill(c(9))
    expect(supermoveLimit(b, 7)).toBe(2)
  })
  test('alternate descending runs obey exact capacity and any empty accepts a single', () => {
    const b = board()
    b.cascades.forEach((p, i) => p.push(c(13, i % 4)))
    b.cascades[0] = [c(7, 0), c(6, 1), c(5, 3)]
    b.cascades[1] = [c(8, 2)]
    b.free = [c(9), c(9, 1), c(9, 2), null]
    expect(legal(b, { kind: 'cascade', index: 0, depth: 0 }, { kind: 'cascade', index: 1 })).toBe(false)
    b.free[0] = null
    expect(legal(b, { kind: 'cascade', index: 0, depth: 0 }, { kind: 'cascade', index: 1 })).toBe(true)
    b.cascades[1] = []
    expect(legal(b, { kind: 'cascade', index: 0, depth: 2 }, { kind: 'cascade', index: 1 })).toBe(true)
  })
  test('safe home aces and twos unconditional, higher need both opposite predecessors', () => {
    const b = board()
    expect(safeHome(b, c(1))).toBe(true)
    b.home[0] = home(1, 0)
    expect(safeHome(b, c(2))).toBe(true)
    b.home[0] = home(4, 0)
    b.home[1] = home(4, 1)
    b.home[2] = home(3, 2)
    expect(safeHome(b, c(5))).toBe(false)
    b.home[2] = home(4, 2)
    expect(safeHome(b, c(5))).toBe(true)
    b.home[0] = home(3, 0)
    expect(safeHome(b, c(5))).toBe(false)
  })
  test('auto home repeats and undo restores all auto moves atomically', () => {
    const b = board()
    b.cascades[0] = [c(2), c(1)]
    b.cascades[1] = [c(2, 1), c(1, 1)]
    b.cascades[2] = [c(9, 3)]
    const g = game(b)
    const before = snapshot(g)
    const next = move(g, { kind: 'cascade', index: 2 }, { kind: 'free', index: 0 })!
    expect(next.home.map(cards => cards.length)).toEqual([2, 2, 0, 0])
    expect(next.history).toHaveLength(1)
    expect(snapshot(undo(next))).toEqual(before)
    const next2 = move(next, { kind: 'free', index: 0 }, { kind: 'cascade', index: 3 })!
    expect(snapshot(undo(undo(next2)))).toEqual(before)
  })
  test('win detection, no legal moves and cheat deferred until a legal move', () => {
    const b = board()
    b.home = SUITS.map((_, suit) => home(13, suit))
    expect(won(b)).toBe(true)
    expect(cardsLeft(b)).toBe(0)
    expect(hasLegalMove(b)).toBe(false)
    b.home[0] = home(12, 0)
    expect(won(b)).toBe(false)
    const g = deal(1)
    g.cheat = true
    expect(won(g)).toBe(false)
    const next = move(g, { kind: 'cascade', index: 0 }, { kind: 'free', index: 0 })!
    expect(won(next)).toBe(true)
    expect(cardsLeft(next)).toBe(0)
    expect(won(undo(next))).toBe(false)
  })
  test('auto play does not send unsafe higher cards', () => {
    const b = board()
    b.home[0] = home(4, 0)
    b.cascades[0] = [c(5)]
    autoHome(b)
    expect(b.home[0]).toEqual(home(4, 0))
  })
  test('ordinary final home move wins, undo restores the last King', () => {
    const b = board()
    b.home = [home(12, 0), home(13, 1), home(13, 2), home(13, 3)]
    b.cascades[0] = [c(13)]
    const g = game(b)
    const next = move(g, { kind: 'cascade', index: 0 }, { kind: 'home', index: 0 })!
    expect(won(next)).toBe(true)
    expect(cardsLeft(next)).toBe(0)
    expect(snapshot(undo(next))).toEqual(snapshot(g))
  })
  test('full cells and same-color exposed Kings give no legal move', () => {
    const b = board()
    b.cascades.forEach(p => p.push(c(13)))
    b.free.fill(c(13))
    expect(hasLegalMove(b)).toBe(false)
  })
  test('statistics streak changes reset direction and preserve records', () => {
    let s = emptyStats()
    for (const win of [true, true, false, false, false, true]) s = record(s, win)
    expect(s).toEqual({ won: 3, lost: 3, bestWins: 2, bestLosses: 3, streak: 1 })
  })
  test('selection range includes hidden games and rejects other numbers', () => {
    for (const n of [1, 32000, -1, -2]) expect(validNumber(n)).toBe(true)
    for (const n of [0, 32001, -3, 1.5, NaN]) expect(validNumber(n)).toBe(false)
  })
  test('any Ace binds any empty home; visual top, safe autoplay and undo retain indexed suits', () => {
    for (let suit = 0; suit < 4; suit++) for (let index = 0; index < 4; index++) {
      const b = board()
      b.cascades[0] = [c(1, suit)]
      expect(legal(b, { kind: 'cascade', index: 0 }, { kind: 'home', index })).toBe(true)
      const next = move(game(b), { kind: 'cascade', index: 0 }, { kind: 'home', index })!
      expect(at(next, { kind: 'home', index })).toEqual(c(1, suit))
      expect(homeIndex(next, c(2, suit))).toBe(index)
      expect(snapshot(undo(next))).toEqual(b)
    }
    const b = board()
    b.home = [home(4, 2), home(4, 3), home(4, 1), home(4, 0)]
    b.free[0] = c(5, 0)
    expect(safeHome(b, c(5, 0))).toBe(true)
    expect(legal(b, { kind: 'free', index: 0 }, { kind: 'home', index: 0 })).toBe(false)
    autoHome(b)
    expect(b.home[3]).toEqual(home(5, 0))
    expect(b.free[0]).toBeNull()
    const copy = snapshot(b)
    copy.home[3].pop()
    expect(b.home[3]).toHaveLength(5)
  })
  test('keyboard selects longest ordered suffix and targets longest legal capacity suffix', () => {
    const b = board()
    b.cascades.forEach(p => p.push(c(13)))
    b.cascades[0] = [c(9, 0), c(7, 0), c(6, 1), c(5, 3)]
    b.cascades[1] = []
    b.free = [c(9), c(9, 1), c(9, 2), null]
    const source = { kind: 'cascade' as const, index: 0 }
    const target = { kind: 'cascade' as const, index: 1 }
    expect(selectSource(b, source).depth).toBe(1)
    const resolved = moveSource(b, source, target)
    expect(resolved.depth).toBe(2)
    expect(asksColumn(b, resolved, target)).toBe(true)
    expect(moveSource(b, { ...source, depth: 1 }, target).depth).toBe(1)
    expect(asksColumn(b, { ...source, depth: 1 }, target)).toBe(false)
    const column = move(game(b), resolved, target)!
    expect(column.cascades[1]).toEqual([c(6, 1), c(5, 3)])
    const single = move(game(b), { ...resolved, depth: 3 }, target)!
    expect(single.cascades[1]).toEqual([c(5, 3)])
    expect(asksColumn(b, { ...resolved, depth: 3 }, target)).toBe(false)
    b.cascades[1] = [c(7, 3)]
    expect(moveSource(b, source, target).depth).toBe(2)
    b.cascades[0][2].faceUp = false
    expect(selectSource(b, source).depth).toBe(3)
  })
  test('cascade geometry fits long runs and uses Pocket height before compressing', () => {
    const b = board()
    for (const count of [9, 13, 20, 52]) {
      b.cascades[0] = Array.from({ length: count }, () => c(9))
      const gap = cascadeGap(b, 402)
      expect(120 + (count - 1) * gap + 96).toBeLessThanOrEqual(402)
    }
    b.cascades[0] = Array.from({ length: 9 }, () => c(9))
    expect(cascadeGap(b, 1000, 0.5, true) * 0.5).toBe(48)
    expect(cascadeGap(b, 402, 0.5, true) * 0.5).toBeLessThan(32)
  })
  test('current streak copy uses singular only for one', () => {
    expect(S.currentStreak(1)).toBe('1 Win')
    expect(S.currentStreak(-1)).toBe('1 Loss')
    expect(S.currentStreak(2)).toBe('2 Wins')
    expect(S.currentStreak(-2)).toBe('2 Losses')
    expect(S.currentStreak(0)).toBe('0 Wins')
  })
  test('covered-card peek is non-mutating and exposed cards do not peek', () => {
    const g = deal(617)
    const before = snapshot(g)
    expect(peekSource(g, 7, 0)).toEqual({ kind: 'cascade', index: 7, depth: 0 })
    expect(peekSource(g, 7, g.cascades[7].length - 1)).toBeNull()
    expect(peekSource(g, 7, -1)).toBeNull()
    expect(snapshot(g)).toEqual(before)
    expect(g.moves).toBe(0)
    expect(g.history).toHaveLength(0)
  })
  test('close and changed-deal requests resign only moved, unfinished games', () => {
    const g = deal(617)
    expect(needsResign(g, false)).toBe(false)
    const moved = move(g, { kind: 'cascade', index: 4 }, { kind: 'cascade', index: 7 })!
    expect(needsResign(moved, false)).toBe(true)
    expect(needsResign(moved, true)).toBe(false)
    const resigned = record(emptyStats(), false)
    expect(resigned.lost).toBe(1)
    expect(resigned.streak).toBe(-1)
  })
  test('exposed mouse selection matches keyboard supermove on game 617; covered and drag depths remain explicit', () => {
    const initial = deal(617)
    const setup = move(initial, { kind: 'cascade', index: 4 }, { kind: 'cascade', index: 7 })!
    const target = { kind: 'cascade' as const, index: 1 }
    const depth = setup.cascades[7].length - 1
    const clicked = pointerSource(setup, 7, depth)
    expect(clicked).toEqual({ kind: 'cascade', index: 7 })
    expect(selectSource(setup, clicked).depth).toBe(depth - 1)
    const mouse = move(setup, moveSource(setup, clicked, target), target)!
    const keyboard = move(setup, moveSource(setup, { kind: 'cascade', index: 7 }, target), target)!
    expect(mouse).toEqual(keyboard)
    expect(mouse.cascades[1].slice(-2)).toEqual([c(12, 2), c(11, 0)])
    expect(pointerSource(setup, 7, depth, true).depth).toBe(depth)
    expect(move(setup, moveSource(setup, pointerSource(setup, 7, depth, true), target), target)).toBeNull()
    expect(pointerSource(setup, 7, depth - 1).depth).toBe(depth - 1)
  })
  test('game-number parser accepts the caption minus without disclosing hidden games', () => {
    expect(parseNumber(' −1 ')).toBe(-1)
    expect(parseNumber('−2')).toBe(-2)
    expect(parseNumber('-1')).toBe(-1)
    expect(validNumber(parseNumber('617'))).toBe(true)
    expect(validNumber(parseNumber('−3'))).toBe(false)
    expect(validNumber(parseNumber(''))).toBe(false)
    expect(validNumber(parseNumber('not a number'))).toBe(false)
    expect(S.caption(-1)).toBe('FreeCell Game #−1')
    expect(S.validation).not.toContain('−1')
    expect(S.validation).not.toContain('−2')
  })
  test('natural terminal and cheat wins schedule every newly homed card in suit-rank order', () => {
    const b = board()
    b.home = SUITS.map((_, suit) => home(11, suit))
    b.cascades[0] = [c(13), c(12)]
    b.cascades[1] = [c(13, 1), c(12, 1)]
    b.cascades[2] = [c(13, 2), c(12, 2)]
    b.cascades[3] = [c(13, 3), c(12, 3)]
    const natural = move(game(b), { kind: 'cascade', index: 0, depth: 1 }, { kind: 'free', index: 0 })!
    expect(won(natural)).toBe(true)
    const sequence = homeSequence(b, natural)
    expect(sequence).toHaveLength(8)
    expect(sequence.map(({ card }) => card.rank)).toEqual([12, 12, 12, 12, 13, 13, 13, 13])
    const cheated = { ...deal(617), cheat: true }
    const next = move(cheated, { kind: 'cascade', index: 0 }, { kind: 'free', index: 0 })!
    const all = homeSequence(cheated, next)
    expect(all).toHaveLength(52)
    expect(new Set(all.map(({ card }) => card.id)).size).toBe(52)
    for (let index = 0; index < 4; index++) {
      expect(all.filter(item => item.index === index).map(({ card }) => card.rank)).toEqual(Array.from({ length: 13 }, (_, i) => i + 1))
    }
  })
})
